from sympy import isprime, primerange

def check_conditions(p, q, r):
    if not (p < q < r):
        return False
    if not (isprime(p) and isprime(q) and isprime(r)):
        return False

    s1 = p + q - r
    s2 = q + r - p
    s3 = r + p - q
    s4 = p + q + r

    if isprime(s1) and isprime(s2) and isprime(s3) and isprime(s4):
        return True
    return False

all_triples = []

# Case 1: p + q = 800
for p in primerange(2, 400):
    q = 800 - p
    if isprime(q) and p < q:
        for r in primerange(q + 1, 1000): # Increased search range slightly just in case
            if check_conditions(p, q, r):
                all_triples.append((p, q, r))

# Case 2: p + r = 800
for p in primerange(2, 400):
    r = 800 - p
    if isprime(r):
        for q in primerange(p + 1, r):
            if check_conditions(p, q, r):
                all_triples.append((p, q, r))

# Case 3: q + r = 800
for q in primerange(2, 400):
    r = 800 - q
    if isprime(r) and q < r:
        for p in primerange(2, q):
            if check_conditions(p, q, r):
                all_triples.append((p, q, r))

print(all_triples)
if all_triples:
    max_r = max(t[2] for t in all_triples)
    print(f"Max r: {max_r}")

