from sympy import isprime, primerange

def check_conditions(p, q, r):
    if not (p < q < r):
        return False
    s1 = p + q - r
    s2 = q + r - p
    s3 = r + p - q
    s4 = p + q + r
    if isprime(s1) and isprime(s2) and isprime(s3) and isprime(s4):
        return True
    return False

r_val = 769
found = False
# Case 1: p+q=800
# r=769. We already checked this, but let's be sure.
for p in primerange(2, 400):
    q = 800 - p
    if isprime(q) and p < q < r_val:
        if check_conditions(p, q, r_val):
            print(f"Found in Case 1: p={p}, q={q}, r={r_val}")
            found = True

# Case 2: p+r=800
# p = 800 - 769 = 31.
p = 800 - r_val
if isprime(p):
    for q in primerange(p + 1, r_val):
        if check_conditions(p, q, r_val):
            print(f"Found in Case 2: p={p}, q={q}, r={r_val}")
            found = True

# Case 3: q+r=800
# q = 800 - 769 = 31.
q = 800 - r_val
if isprime(q):
    for p in primerange(2, q):
        if check_conditions(p, q, r_val):
            print(f"Found in Case 3: p={p}, q={q}, r={r_val}")
            found = True

if not found:
